import (
	"bufio"
	"fmt"
	"os"
)

const mod int64 = 998244353

var powers []int64

func initPowers(n int64, k int) {
	powers = make([]int64, k)
	powers[0] = 1
	for i := 1; i < k; i++ {
		powers[i] = (n * powers[i-1]) % mod
	}
}

func solve(n int, a, x, y int64, k int, m int64) {
	initPowers(int64(n), k)

	gcdR := gcdRange(int64(k - 1))
	r := make([][]int64, gcdR)
	for i := range r {
		r[i] = make([]int64, k+1)
	}

	for i := 1; i <= k; i++ {
		for j := 0; j < gcdR; j++ {
			jump := j - j%(k+1-i)
			r[j][i] = (int64(n-1)*r[j][i-1] +
				r[jump][i-1] + int64(j)*powers[i-1]) % mod
		}
	}

	var sum int64
	for i := 0; i < n; i++ {
		sum += r[int(a%int64(gcdR))][k] +
			(((a/int64(gcdR))*int64(gcdR)*int64(k))%mod)*powers[k-1]%mod
		sum %= mod
		a = (a*x + y) % m
	}

	fmt.Println(sum)
}

